style.css:
@-moz-document domain("monarch.aop.com") {
/* Background */
  html, body {
    background: #ffcadd !important;
  }

  /* Buttons (like Submit Answer) */
  button,
  input[type="button"],
  input[type="submit"] {
    background-color: #ffcadd !important;
    border-color: #ffcadd !important;
    color: #000 !important;
  }

  /* Headers / sections like "Read and Questions" */
  h1, h2, h3, .section-title {
    background-color: #ffcadd !important;
    color: #000 !important;
  }
}
